const crypto=require('crypto');
const multer=require('multer');
const {storage}=require('../../config/cloudinary');
const podUpload=multer({storage});
const Organization=require('../../models/platform/Organization');
const Warehouse=require('../../models/platform/Warehouse');
const ItemMaster=require('../../models/platform/ItemMaster');
const InventoryBalance=require('../../models/platform/InventoryBalance');
const InventorySerial=require('../../models/platform/InventorySerial');
const StockMovement=require('../../models/platform/StockMovement');
const Driver=require('../../models/platform/Driver');
const Vehicle=require('../../models/platform/Vehicle');
const Shipment=require('../../models/platform/Shipment');
const TrackingEvent=require('../../models/platform/TrackingEvent');
const MaterialIssue=require('../../models/platform/MaterialIssue');
const User=require('../../models/User');
const AgencyUserLink=require('../../models/platform/AgencyUserLink');
const WorkPackage=require('../../models/platform/WorkPackage');
const BeneficiaryContext=require('../../models/platform/BeneficiaryContext');
const platformAudit=require('../../utils/platformAudit');
const text=v=>String(v??'').trim();
const companyIdFor=req=>req.platformUser.role==='platform_superadmin'?(req.query.companyId||req.body.companyId):String(req.tenant.companyId||'');
async function company(req,res){const id=companyIdFor(req);if(!id){res.status(400).json({message:'Company context is required.'});return null;}const c=await Organization.findOne({_id:id,type:'COMPANY',status:{$ne:'ARCHIVED'}});if(!c){res.status(404).json({message:'Company not found.'});return null;}return c;}
async function balance(companyId,warehouseId,itemId,onHandDelta=0,inTransitDelta=0){const b=await InventoryBalance.findOne({companyId,warehouseId,itemId});const nextOn=Number(b?.onHand||0)+onHandDelta,nextTransit=Number(b?.inTransit||0)+inTransitDelta;if(nextOn<0||nextTransit<0)throw new Error('Inventory balance would become negative.');return InventoryBalance.findOneAndUpdate({companyId,warehouseId,itemId},{$set:{onHand:nextOn,inTransit:nextTransit,lastMovementAt:new Date()}},{upsert:true,new:true,setDefaultsOnInsert:true});}
const hashToken=t=>crypto.createHash('sha256').update(t).digest('hex');
exports.dashboard=async(req,res)=>{const c=await company(req,res);if(!c)return;const q={companyId:c._id};const [drivers,vehicles,shipments,inTransit,delivered,issues,latest]=await Promise.all([Driver.countDocuments({...q,isActive:true}),Vehicle.countDocuments({...q,isActive:true}),Shipment.countDocuments(q),Shipment.countDocuments({...q,status:'IN_TRANSIT'}),Shipment.countDocuments({...q,status:'DELIVERED'}),MaterialIssue.countDocuments({...q,status:{$in:['ISSUED','PARTIALLY_RETURNED']}}),Shipment.find(q).populate('driverId','name mobile lastLocation').populate('vehicleId','registrationNo type').populate('agencyId','name code').sort({updatedAt:-1}).limit(8).lean()]);res.json({drivers,vehicles,shipments,inTransit,delivered,openMaterialIssues:issues,recentShipments:latest});};
exports.listDrivers=async(req,res)=>{const c=await company(req,res);if(!c)return;res.json({items:await Driver.find({companyId:c._id}).sort({name:1}).lean()});};
exports.createDriver=async(req,res)=>{const c=await company(req,res);if(!c)return;const b=req.body;if(!text(b.name)||!text(b.mobile))return res.status(400).json({message:'Driver name and mobile are required.'});const d=await Driver.create({companyId:c._id,name:text(b.name),mobile:text(b.mobile),licenseNumber:text(b.licenseNumber),isActive:true});await platformAudit(req,{companyId:c._id,organizationId:c._id,action:'DRIVER_CREATED',entityType:'Driver',entityId:d._id,after:d.toObject()});res.status(201).json({item:d});};
exports.listVehicles=async(req,res)=>{const c=await company(req,res);if(!c)return;res.json({items:await Vehicle.find({companyId:c._id}).sort({registrationNo:1}).lean()});};
exports.createVehicle=async(req,res)=>{const c=await company(req,res);if(!c)return;const b=req.body;if(!text(b.registrationNo))return res.status(400).json({message:'Vehicle registration number is required.'});const v=await Vehicle.create({companyId:c._id,registrationNo:text(b.registrationNo).toUpperCase(),type:text(b.type),capacity:text(b.capacity),isActive:true});await platformAudit(req,{companyId:c._id,organizationId:c._id,action:'VEHICLE_CREATED',entityType:'Vehicle',entityId:v._id,after:v.toObject()});res.status(201).json({item:v});};
exports.refs=async(req,res)=>{const c=await company(req,res);if(!c)return;const [warehouses,items,drivers,vehicles,agencies,technicians,agencyUserLinks,workPackages]=await Promise.all([Warehouse.find({companyId:c._id,isActive:true}).sort({name:1}).lean(),ItemMaster.find({companyId:c._id,isActive:true}).sort({name:1}).lean(),Driver.find({companyId:c._id,isActive:true}).sort({name:1}).lean(),Vehicle.find({companyId:c._id,isActive:true}).sort({registrationNo:1}).lean(),Organization.find({parentOrganization:c._id,type:'AGENCY',status:'ACTIVE'}).sort({name:1}).lean(),User.find({role:'field_technician',isActive:true}).select('username mobile').sort({username:1}).lean(),AgencyUserLink.find({companyId:c._id,isActive:true,role:'field_technician'}).populate('legacyUserId','username mobile role').lean(),WorkPackage.find({companyId:c._id,status:{$ne:'CLOSED'}}).select('code name agencyId status geography').sort({updatedAt:-1}).limit(1000).lean()]);res.json({warehouses,items,drivers,vehicles,agencies,technicians,agencyUserLinks,workPackages});};
exports.listShipments=async(req,res)=>{const c=await company(req,res);if(!c)return;const page=Math.max(1,Number(req.query.page||1)),pageSize=Math.min(100,Math.max(10,Number(req.query.pageSize||25)));const q={companyId:c._id};if(req.query.status)q.status=req.query.status;if(req.query.agencyId)q.agencyId=req.query.agencyId;if(req.query.workPackageId)q.workPackageId=req.query.workPackageId;if(req.query.q){const rx=new RegExp(text(req.query.q).slice(0,80).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i');q.shipmentNo=rx;}const [total,items]=await Promise.all([Shipment.countDocuments(q),Shipment.find(q).populate('workPackageId','code name status geography').populate('fromWarehouseId','code name').populate('toWarehouseId','code name').populate('agencyId','code name').populate('driverId','name mobile lastLocation').populate('vehicleId','registrationNo type').populate('items.itemId','sku name serialTracked').sort({createdAt:-1}).skip((page-1)*pageSize).limit(pageSize).lean()]);res.json({items,total,page,pageSize,pages:Math.max(1,Math.ceil(total/pageSize))});};
exports.createShipment=async(req,res)=>{const c=await company(req,res);if(!c)return;const b=req.body;if(!text(b.shipmentNo)||!b.fromWarehouseId||!b.toWarehouseId||!Array.isArray(b.items)||!b.items.length)return res.status(400).json({message:'Shipment number, source, destination and items are required.'});const [from,to]=await Promise.all([Warehouse.findOne({_id:b.fromWarehouseId,companyId:c._id,isActive:true}),Warehouse.findOne({_id:b.toWarehouseId,companyId:c._id,isActive:true})]);if(!from||!to)return res.status(400).json({message:'Invalid shipment warehouse.'});if(String(from._id)===String(to._id))return res.status(400).json({message:'Source and destination warehouse must differ.'});const items=[];for(const line of b.items){const item=await ItemMaster.findOne({_id:line.itemId,companyId:c._id,isActive:true});const qty=Number(line.quantity||0);if(!item||qty<=0)return res.status(400).json({message:'Invalid shipment item or quantity.'});const bal=await InventoryBalance.findOne({companyId:c._id,warehouseId:from._id,itemId:item._id});if(!bal||Number(bal.onHand)<qty)return res.status(409).json({message:`Insufficient stock for ${item.name}.`});let serialIds=[];if(item.serialTracked){const codes=(line.serials||[]).map(text).filter(Boolean);if(codes.length!==qty)return res.status(400).json({message:`Exactly ${qty} serial/barcode values required for ${item.name}.`});const docs=await InventorySerial.find({companyId:c._id,itemId:item._id,warehouseId:from._id,status:'AVAILABLE',$or:[{serialNumber:{$in:codes}},{barcodeValue:{$in:codes}}]});if(docs.length!==qty)return res.status(409).json({message:`One or more serials for ${item.name} are unavailable or invalid.`});serialIds=docs.map(x=>x._id);}items.push({itemId:item._id,quantity:qty,serialIds,receivedQty:0});}
const s=await Shipment.create({companyId:c._id,shipmentNo:text(b.shipmentNo).toUpperCase(),workPackageId:b.workPackageId||null,fromWarehouseId:from._id,toWarehouseId:to._id,agencyId:b.agencyId||to.organizationId||null,driverId:b.driverId||null,vehicleId:b.vehicleId||null,items,status:'DRAFT'});await platformAudit(req,{companyId:c._id,organizationId:c._id,action:'SHIPMENT_CREATED',entityType:'Shipment',entityId:s._id,after:s.toObject()});res.status(201).json({item:s});};
exports.cancelShipment=async(req,res)=>{const c=await company(req,res);if(!c)return;const shipment=await Shipment.findOne({_id:req.params.id,companyId:c._id});if(!shipment)return res.status(404).json({message:'Shipment not found.'});if(shipment.status!=='DRAFT')return res.status(409).json({message:'Only draft shipments can be cancelled. In-transit material must be reconciled through receipt/return workflows.'});const before=shipment.toObject();shipment.status='CANCELLED';shipment.proofOfDelivery={...(shipment.proofOfDelivery||{}),cancelReason:text(req.body.reason),cancelledAt:new Date()};await shipment.save();await platformAudit(req,{companyId:c._id,organizationId:shipment.agencyId||c._id,action:'SHIPMENT_CANCELLED',entityType:'Shipment',entityId:shipment._id,before,after:shipment.toObject(),reason:text(req.body.reason)});res.json({item:shipment});};

exports.dispatchShipment=async(req,res)=>{const c=await company(req,res);if(!c)return;const s=await Shipment.findOne({_id:req.params.id,companyId:c._id});if(!s)return res.status(404).json({message:'Shipment not found.'});if(s.status!=='DRAFT')return res.status(409).json({message:'Only draft shipments can be dispatched.'});for(const line of s.items){await balance(c._id,s.fromWarehouseId,line.itemId,-Number(line.quantity),Number(line.quantity));if(line.serialIds?.length)await InventorySerial.updateMany({_id:{$in:line.serialIds},companyId:c._id},{$set:{status:'IN_TRANSIT',warehouseId:null,agencyId:s.agencyId||null}});await StockMovement.create({companyId:c._id,itemId:line.itemId,serialIds:line.serialIds||[],quantity:line.quantity,movementType:'DISPATCH',fromWarehouseId:s.fromWarehouseId,toWarehouseId:s.toWarehouseId,fromOrganizationId:c._id,toOrganizationId:s.agencyId||c._id,referenceType:'Shipment',referenceId:s._id,reason:`Shipment ${s.shipmentNo}`,performedBy:req.platformUser._id});}
const raw=crypto.randomBytes(32).toString('hex');s.status='IN_TRANSIT';s.dispatchedAt=new Date();s.trackingTokenHash=hashToken(raw);s.trackingExpiresAt=new Date(Date.now()+1000*60*60*24*7);await s.save();await platformAudit(req,{companyId:c._id,organizationId:c._id,action:'SHIPMENT_DISPATCHED',entityType:'Shipment',entityId:s._id,after:s.toObject()});res.json({item:s,trackingToken:raw,trackingPath:`/track/${raw}`});};
exports.receiveShipment=async(req,res)=>{const c=await company(req,res);if(!c)return;const s=await Shipment.findOne({_id:req.params.id,companyId:c._id});if(!s)return res.status(404).json({message:'Shipment not found.'});if(!['IN_TRANSIT','PARTIAL'].includes(s.status))return res.status(409).json({message:'Shipment is not receivable in its current state.'});let receipts=[];try{receipts=typeof req.body.receipts==='string'?JSON.parse(req.body.receipts):(req.body.receipts||[])}catch{return res.status(400).json({message:'Invalid receipt detail payload.'})}let fullyAccounted=true;for(const line of s.items){const itemId=String(line.itemId);const r=receipts.find(x=>String(x.itemId)===itemId)||{};const previously=Number(line.receivedQty||0)+Number(line.damagedQty||0)+Number(line.missingQty||0);const remaining=Math.max(0,Number(line.quantity)-previously);const good=Math.max(0,Number(r.receivedQty??remaining));const damaged=Math.max(0,Number(r.damagedQty||0));const missing=Math.max(0,Number(r.missingQty||0));const accounted=good+damaged+missing;if(accounted>remaining)return res.status(400).json({message:'Receipt quantities exceed the remaining shipment quantity.'});if(accounted<remaining)fullyAccounted=false;const allCodes=[...(r.receivedSerials||[]),...(r.damagedSerials||[]),...(r.missingSerials||[])].map(text).filter(Boolean);if(line.serialIds?.length){if(allCodes.length!==accounted)return res.status(400).json({message:'Serialized receipt requires one serial/barcode for every received, damaged or missing unit.'});const docs=await InventorySerial.find({_id:{$in:line.serialIds},companyId:c._id,status:'IN_TRANSIT',$or:[{serialNumber:{$in:allCodes}},{barcodeValue:{$in:allCodes}}]});if(docs.length!==accounted)return res.status(409).json({message:'One or more receipt serials are invalid, duplicated, or no longer in transit.'});const map=new Map();for(const d of docs){map.set(String(d.serialNumber).toLowerCase(),d);if(d.barcodeValue)map.set(String(d.barcodeValue).toLowerCase(),d)}for(const code of r.receivedSerials||[]){const d=map.get(text(code).toLowerCase());d.status=s.agencyId?'AGENCY_STOCK':'AVAILABLE';d.warehouseId=s.toWarehouseId;d.agencyId=s.agencyId||null;await d.save()}for(const code of r.damagedSerials||[]){const d=map.get(text(code).toLowerCase());d.status='DAMAGED';d.warehouseId=null;d.metadata={...(d.metadata||{}),damageReason:text(r.notes)||'Damaged in shipment',damagedAt:new Date()};await d.save()}for(const code of r.missingSerials||[]){const d=map.get(text(code).toLowerCase());d.status='MISSING';d.warehouseId=null;d.metadata={...(d.metadata||{}),missingReason:text(r.notes)||'Missing at shipment receipt',missingAt:new Date()};await d.save()}}
 if(accounted>0)await balance(c._id,s.fromWarehouseId,line.itemId,0,-accounted);if(good>0)await balance(c._id,s.toWarehouseId,line.itemId,good,0);if(good>0)await StockMovement.create({companyId:c._id,itemId:line.itemId,quantity:good,movementType:'TRANSFER',fromWarehouseId:s.fromWarehouseId,toWarehouseId:s.toWarehouseId,fromOrganizationId:c._id,toOrganizationId:s.agencyId||c._id,referenceType:'Shipment',referenceId:s._id,reason:`Shipment receipt ${s.shipmentNo}`,performedBy:req.platformUser._id});if(damaged>0)await StockMovement.create({companyId:c._id,itemId:line.itemId,quantity:damaged,movementType:'DAMAGE',fromWarehouseId:s.fromWarehouseId,toOrganizationId:s.agencyId||c._id,referenceType:'Shipment',referenceId:s._id,reason:text(r.notes)||`Damaged during shipment ${s.shipmentNo}`,performedBy:req.platformUser._id});if(missing>0)await StockMovement.create({companyId:c._id,itemId:line.itemId,quantity:missing,movementType:'ADJUSTMENT',fromWarehouseId:s.fromWarehouseId,toOrganizationId:s.agencyId||c._id,referenceType:'Shipment',referenceId:s._id,reason:text(r.notes)||`Missing during shipment ${s.shipmentNo}`,performedBy:req.platformUser._id});line.receivedQty=Number(line.receivedQty||0)+good;line.damagedQty=Number(line.damagedQty||0)+damaged;line.missingQty=Number(line.missingQty||0)+missing;line.receiptNotes=text(r.notes)||line.receiptNotes||'';}
s.status=fullyAccounted?'DELIVERED':'PARTIAL';if(fullyAccounted)s.deliveredAt=new Date();s.proofOfDelivery={receiverName:text(req.body.receiverName),receiverMobile:text(req.body.receiverMobile),notes:text(req.body.notes),receivedAt:new Date(),photoUrl:req.files?.podPhoto?.[0]?.path||'',signatureUrl:req.files?.podSignature?.[0]?.path||''};await s.save();await platformAudit(req,{companyId:c._id,organizationId:c._id,action:fullyAccounted?'SHIPMENT_RECEIVED':'SHIPMENT_PARTIAL_RECEIPT',entityType:'Shipment',entityId:s._id,after:s.toObject()});res.json({item:s});};
exports.podUpload=podUpload.fields([{name:'podPhoto',maxCount:1},{name:'podSignature',maxCount:1}]);
exports.shipmentTracking=async(req,res)=>{const c=await company(req,res);if(!c)return;const s=await Shipment.findOne({_id:req.params.id,companyId:c._id}).populate('driverId','name mobile lastLocation').populate('vehicleId','registrationNo type').populate('agencyId','name code').populate('fromWarehouseId','name code location').populate('toWarehouseId','name code location').lean();if(!s)return res.status(404).json({message:'Shipment not found.'});const events=await TrackingEvent.find({shipmentId:s._id,companyId:c._id}).sort({capturedAt:-1}).limit(250).lean();res.json({shipment:s,events});};
exports.issueMaterial=async(req,res)=>{
 const c=await company(req,res);if(!c)return;const b=req.body;
 if(!b.agencyId||!b.warehouseId||!b.technicianUserId||!Array.isArray(b.items)||!b.items.length)return res.status(400).json({message:'Agency, warehouse, technician and issue items are required.'});
 const [agency,tech,wh]=await Promise.all([Organization.findOne({_id:b.agencyId,parentOrganization:c._id,type:'AGENCY',status:'ACTIVE'}),User.findOne({_id:b.technicianUserId,role:'field_technician',isActive:true}),Warehouse.findOne({_id:b.warehouseId,companyId:c._id,isActive:true})]);
 if(!agency)return res.status(400).json({message:'Invalid or inactive Agency for this company.'});if(!tech)return res.status(400).json({message:'Invalid technician.'});if(!wh)return res.status(400).json({message:'Invalid warehouse.'});
 const link=await AgencyUserLink.findOne({companyId:c._id,agencyId:agency._id,legacyUserId:tech._id,isActive:true,role:'field_technician'});if(!link)return res.status(409).json({message:'Technician is not mapped to the selected agency. Create the agency-technician link first.'});
 let pkg=null,beneficiary=null;
 if(b.workPackageId){pkg=await WorkPackage.findOne({_id:b.workPackageId,companyId:c._id,agencyId:agency._id,status:{$ne:'CLOSED'}});if(!pkg)return res.status(409).json({message:'Work package does not belong to the selected Company/Agency or is closed.'});}
 if(b.farmerId){beneficiary=await BeneficiaryContext.findOne({companyId:c._id,agencyId:agency._id,farmerId:b.farmerId});if(!beneficiary)return res.status(409).json({message:'Beneficiary does not belong to the selected Company/Agency.'});if(pkg&&String(beneficiary.workPackageId)!==String(pkg._id))return res.status(409).json({message:'Beneficiary is not assigned to the selected work package.'});if(!pkg&&beneficiary.workPackageId)pkg=await WorkPackage.findOne({_id:beneficiary.workPackageId,companyId:c._id});}
 const lines=[],movementRows=[];
 for(const line of b.items){
  const item=await ItemMaster.findOne({_id:line.itemId,companyId:c._id,isActive:true});const qty=Number(line.quantity||0);if(!item||qty<=0)return res.status(400).json({message:'Invalid material issue line.'});
  const bal=await InventoryBalance.findOne({companyId:c._id,warehouseId:wh._id,itemId:item._id});if(!bal||bal.onHand<qty)return res.status(409).json({message:`Insufficient stock for ${item.name}.`});
  let serialIds=[];
  if(item.serialTracked){
   const codes=(line.serials||[]).map(text).filter(Boolean);if(codes.length!==qty||new Set(codes.map(x=>x.toLowerCase())).size!==codes.length)return res.status(400).json({message:`Exactly ${qty} unique serial/barcode values required for ${item.name}.`});
   const docs=await InventorySerial.find({companyId:c._id,itemId:item._id,warehouseId:wh._id,$or:[{status:'AVAILABLE'},{status:'AGENCY_STOCK',agencyId:agency._id}],$and:[{$or:[{serialNumber:{$in:codes}},{barcodeValue:{$in:codes}}]}]});
   if(docs.length!==qty)return res.status(409).json({message:`One or more serials for ${item.name} are unavailable, belong to another Agency, or are not in the selected warehouse.`});
   serialIds=docs.map(x=>x._id);
   for(const serial of docs){serial.status='ISSUED';serial.agencyId=agency._id;serial.farmerId=b.farmerId||null;serial.metadata={...(serial.metadata||{}),technicianUserId:String(tech._id),technicianMobile:tech.mobile,issuedAt:new Date(),workPackageId:String(pkg?._id||''),beneficiaryId:String(b.farmerId||'')};await serial.save();}
  }
  await balance(c._id,wh._id,item._id,-qty,0);lines.push({itemId:item._id,quantity:qty,serialIds});movementRows.push({itemId:item._id,serialIds,quantity:qty});
 }
 const issue=await MaterialIssue.create({companyId:c._id,agencyId:agency._id,warehouseId:wh._id,technicianUserId:tech._id,workPackageId:pkg?._id||null,farmerId:b.farmerId||null,issueNo:text(b.issueNo)||`ISS-${Date.now()}`,items:lines,issuedBy:req.platformUser._id,notes:text(b.notes)});
 for(const row of movementRows)await StockMovement.create({companyId:c._id,itemId:row.itemId,serialIds:row.serialIds,quantity:row.quantity,movementType:'ISSUE',fromWarehouseId:wh._id,fromOrganizationId:wh.organizationId||c._id,toOrganizationId:agency._id,referenceType:'MaterialIssue',referenceId:issue._id,reason:`Issued to technician ${tech.username}${b.farmerId?' for beneficiary':''}`,performedBy:req.platformUser._id});
 await platformAudit(req,{companyId:c._id,organizationId:agency._id,action:'MATERIAL_ISSUED_TO_TECHNICIAN',entityType:'MaterialIssue',entityId:issue._id,after:issue.toObject()});res.status(201).json({item:issue});
};
exports.returnIssuedSerial=async(req,res)=>{const c=await company(req,res);if(!c)return;const code=text(req.body.code),warehouseId=req.body.warehouseId;if(!code||!warehouseId)return res.status(400).json({message:'Serial/barcode and destination warehouse are required.'});const wh=await Warehouse.findOne({_id:warehouseId,companyId:c._id,isActive:true});if(!wh)return res.status(400).json({message:'Invalid warehouse.'});const serial=await InventorySerial.findOne({companyId:c._id,status:'ISSUED',$or:[{serialNumber:code},{barcodeValue:code}]}).populate('itemId','name sku');if(!serial)return res.status(409).json({message:'Serial is not currently issued or could not be found.'});serial.status=wh.type==='AGENCY'?'AGENCY_STOCK':'AVAILABLE';serial.warehouseId=wh._id;serial.farmerId=null;serial.metadata={...(serial.metadata||{}),returnedAt:new Date(),returnedReason:text(req.body.reason)};await serial.save();await balance(c._id,wh._id,serial.itemId._id,1,0);await StockMovement.create({companyId:c._id,itemId:serial.itemId._id,serialIds:[serial._id],quantity:1,movementType:'RETURN',toWarehouseId:wh._id,toOrganizationId:wh.organizationId||c._id,referenceType:'InventorySerial',referenceId:serial._id,reason:text(req.body.reason)||'Unused technician material returned',performedBy:req.platformUser._id});const affectedIssues=await MaterialIssue.find({companyId:c._id,'items.serialIds':serial._id,status:{$in:['ISSUED','PARTIALLY_RETURNED']}});for(const issue of affectedIssues){const ids=issue.items.flatMap(x=>(x.serialIds||[]));const remaining=await InventorySerial.countDocuments({_id:{$in:ids},status:'ISSUED'});const installed=await InventorySerial.countDocuments({_id:{$in:ids},status:'INSTALLED'});if(remaining===0)issue.status=installed?'PARTIALLY_RETURNED':'RETURNED';else issue.status='PARTIALLY_RETURNED';await issue.save();}await platformAudit(req,{companyId:c._id,organizationId:serial.agencyId||c._id,action:'ISSUED_SERIAL_RETURNED',entityType:'InventorySerial',entityId:serial._id,after:serial.toObject()});res.json({item:serial});};
exports.markSerialDamaged=async(req,res)=>{const c=await company(req,res);if(!c)return;const code=text(req.body.code);if(!code)return res.status(400).json({message:'Serial/barcode is required.'});const serial=await InventorySerial.findOne({companyId:c._id,$or:[{serialNumber:code},{barcodeValue:code}]});if(!serial)return res.status(404).json({message:'Serial not found.'});if(serial.status==='INSTALLED')return res.status(409).json({message:'Installed assets must be removed/replaced through the asset lifecycle instead of direct damage marking.'});serial.status='DAMAGED';serial.warehouseId=null;serial.metadata={...(serial.metadata||{}),damageReason:text(req.body.reason),damagedAt:new Date()};await serial.save();await StockMovement.create({companyId:c._id,itemId:serial.itemId,serialIds:[serial._id],quantity:1,movementType:'DAMAGE',referenceType:'InventorySerial',referenceId:serial._id,reason:text(req.body.reason)||'Material marked damaged',performedBy:req.platformUser._id});await platformAudit(req,{companyId:c._id,organizationId:serial.agencyId||c._id,action:'SERIAL_MARKED_DAMAGED',entityType:'InventorySerial',entityId:serial._id,after:serial.toObject()});res.json({item:serial});};
