// Phase 39 — scalable supply-chain control tower, fleet workload and safe operational CRUD.
const escapeRx=value=>String(value||'').replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const activeShipmentStatuses=['DRAFT','DISPATCHED','IN_TRANSIT','PARTIAL'];
const activeMovingStatuses=['DISPATCHED','IN_TRANSIT','PARTIAL'];
async function fleetWorkload(companyId){
  const since=new Date(Date.now()-30*86400000);
  const [driverActive,driverDelivered,vehicleActive,vehicleDelivered]=await Promise.all([
    Shipment.aggregate([{$match:{companyId,status:{$in:activeMovingStatuses},driverId:{$ne:null}}},{$group:{_id:'$driverId',active:{$sum:1},nextEta:{$min:'$expectedDeliveryAt'},lastDispatch:{$max:'$dispatchedAt'}}}]),
    Shipment.aggregate([{$match:{companyId,status:'DELIVERED',driverId:{$ne:null},deliveredAt:{$gte:since}}},{$group:{_id:'$driverId',delivered30d:{$sum:1}}}]),
    Shipment.aggregate([{$match:{companyId,status:{$in:activeMovingStatuses},vehicleId:{$ne:null}}},{$group:{_id:'$vehicleId',active:{$sum:1},nextEta:{$min:'$expectedDeliveryAt'},lastDispatch:{$max:'$dispatchedAt'}}}]),
    Shipment.aggregate([{$match:{companyId,status:'DELIVERED',vehicleId:{$ne:null},deliveredAt:{$gte:since}}},{$group:{_id:'$vehicleId',delivered30d:{$sum:1}}}])
  ]);
  const mapRows=(a,b)=>{const m=new Map();for(const x of a)m.set(String(x._id),{active:x.active||0,nextEta:x.nextEta||null,lastDispatch:x.lastDispatch||null,delivered30d:0});for(const x of b){const k=String(x._id),v=m.get(k)||{active:0,nextEta:null,lastDispatch:null,delivered30d:0};v.delivered30d=x.delivered30d||0;m.set(k,v);}return m};
  return {drivers:mapRows(driverActive,driverDelivered),vehicles:mapRows(vehicleActive,vehicleDelivered)};
}

exports.dashboard=async(req,res)=>{
  const c=await company(req,res);if(!c)return;const q={companyId:c._id};const now=new Date();
  const [drivers,vehicles,shipments,inTransit,delivered,issues,exceptions,latest,workload]=await Promise.all([
    Driver.countDocuments({...q,isActive:true}),Vehicle.countDocuments({...q,isActive:true}),Shipment.countDocuments(q),Shipment.countDocuments({...q,status:{$in:['DISPATCHED','IN_TRANSIT','PARTIAL']}}),Shipment.countDocuments({...q,status:'DELIVERED'}),MaterialIssue.countDocuments({...q,status:{$in:['ISSUED','PARTIALLY_RETURNED']}}),Shipment.countDocuments({...q,$or:[{issueFlag:true},{status:'PARTIAL'},{expectedDeliveryAt:{$lt:now},status:{$in:['DISPATCHED','IN_TRANSIT']}}]}),Shipment.find(q).populate('workPackageId','code name geography').populate('driverId','name mobile lastLocation').populate('vehicleId','registrationNo type').populate('agencyId','name code').sort({updatedAt:-1}).limit(10).lean(),fleetWorkload(c._id)
  ]);
  const busyDrivers=[...workload.drivers.values()].filter(x=>x.active>0).length,busyVehicles=[...workload.vehicles.values()].filter(x=>x.active>0).length;
  res.json({drivers,vehicles,availableDrivers:Math.max(0,drivers-busyDrivers),availableVehicles:Math.max(0,vehicles-busyVehicles),shipments,inTransit,delivered,exceptions,openMaterialIssues:issues,recentShipments:latest});
};

exports.controlTower=async(req,res)=>{
  const c=await company(req,res);if(!c)return;const companyId=c._id,now=new Date();
  const [statusRows,agencyRows,workload,drivers,vehicles]=await Promise.all([
    Shipment.aggregate([{$match:{companyId}},{$group:{_id:'$status',count:{$sum:1},units:{$sum:{$sum:'$items.quantity'}}}}]),
    Shipment.aggregate([{$match:{companyId,agencyId:{$ne:null}}},{$group:{_id:'$agencyId',shipments:{$sum:1},units:{$sum:{$sum:'$items.quantity'}},received:{$sum:{$sum:'$items.receivedQty'}},damaged:{$sum:{$sum:'$items.damagedQty'}},missing:{$sum:{$sum:'$items.missingQty'}},lastDispatch:{$max:'$dispatchedAt'},lastDelivery:{$max:'$deliveredAt'}}},{$sort:{units:-1}},{$limit:100}]),
    fleetWorkload(companyId),Driver.find({companyId,isActive:true}).select('name mobile licenseNumber status baseLocation lastLocation').sort({name:1}).lean(),Vehicle.find({companyId,isActive:true}).select('registrationNo type capacity status baseLocation').sort({registrationNo:1}).lean()
  ]);
  const agencyIds=agencyRows.map(x=>x._id),agencies=agencyIds.length?await Organization.find({_id:{$in:agencyIds}}).select('name code state district').lean():[],agencyMap=new Map(agencies.map(x=>[String(x._id),x]));
  const driverRows=drivers.map(x=>({...x,workload:workload.drivers.get(String(x._id))||{active:0,delivered30d:0,nextEta:null,lastDispatch:null},availability:(workload.drivers.get(String(x._id))?.active||0)>0?'BUSY':x.status==='OFF_DUTY'?'OFF_DUTY':'AVAILABLE'}));
  const vehicleRows=vehicles.map(x=>({...x,workload:workload.vehicles.get(String(x._id))||{active:0,delivered30d:0,nextEta:null,lastDispatch:null},availability:(workload.vehicles.get(String(x._id))?.active||0)>0?'BUSY':x.status==='MAINTENANCE'?'MAINTENANCE':'AVAILABLE'}));
  const overdue=await Shipment.countDocuments({companyId,status:{$in:['DISPATCHED','IN_TRANSIT']},expectedDeliveryAt:{$lt:now}});
  res.json({status:statusRows,overdue,agencies:agencyRows.map(x=>({...x,agency:agencyMap.get(String(x._id))||null})),drivers:driverRows,vehicles:vehicleRows});
};

exports.listDrivers=async(req,res)=>{
  const c=await company(req,res);if(!c)return;const page=Math.max(1,Number(req.query.page||1)),pageSize=Math.min(100,Math.max(10,Number(req.query.pageSize||50))),q={companyId:c._id},workload=await fleetWorkload(c._id);
  if(req.query.active==='true')q.isActive=true;if(req.query.status)q.status=req.query.status;if(req.query.q){const rx=new RegExp(escapeRx(text(req.query.q)).slice(0,100),'i');q.$or=[{name:rx},{mobile:rx},{licenseNumber:rx},{baseLocation:rx}];}
  const availability=String(req.query.availability||'').toUpperCase(),busyIds=[...workload.drivers.entries()].filter(([,v])=>Number(v.active||0)>0).map(([id])=>id);if(availability==='BUSY')q._id={$in:busyIds};else if(availability==='AVAILABLE'){q.status='AVAILABLE';if(busyIds.length)q._id={$nin:busyIds};}else if(['OFF_DUTY','INACTIVE'].includes(availability))q.status=availability;
  const [total,items]=await Promise.all([Driver.countDocuments(q),Driver.find(q).sort({isActive:-1,name:1}).skip((page-1)*pageSize).limit(pageSize).lean()]);
  res.json({items:items.map(x=>({...x,workload:workload.drivers.get(String(x._id))||{active:0,delivered30d:0,nextEta:null},availability:(workload.drivers.get(String(x._id))?.active||0)>0?'BUSY':!x.isActive?'INACTIVE':x.status||'AVAILABLE'})),total,page,pageSize,pages:Math.max(1,Math.ceil(total/pageSize))});
};
