exports.createShipment=async(req,res)=>{const c=await company(req,res);if(!c)return;const b=req.body;if(!text(b.shipmentNo)||!b.fromWarehouseId||!b.toWarehouseId||!Array.isArray(b.items)||!b.items.length)return res.status(400).json({message:'Shipment number, source, destination and items are required.'});const [from,to]=await Promise.all([Warehouse.findOne({_id:b.fromWarehouseId,companyId:c._id,isActive:true}),Warehouse.findOne({_id:b.toWarehouseId,companyId:c._id,isActive:true})]);if(!from||!to)return res.status(400).json({message:'Invalid shipment warehouse.'});if(String(from._id)===String(to._id))return res.status(400).json({message:'Source and destination warehouse must differ.'});const items=[];for(const line of b.items){const item=await ItemMaster.findOne({_id:line.itemId,companyId:c._id,isActive:true});const qty=Number(line.quantity||0);if(!item||qty<=0)return res.status(400).json({message:'Invalid shipment item or quantity.'});const bal=await InventoryBalance.findOne({companyId:c._id,warehouseId:from._id,itemId:item._id});if(!bal||Number(bal.onHand)<qty)return res.status(409).json({message:`Insufficient stock for ${item.name}.`});let serialIds=[];if(item.serialTracked){const codes=(line.serials||[]).map(text).filter(Boolean);if(codes.length!==qty)return res.status(400).json({message:`Exactly ${qty} serial/barcode values required for ${item.name}.`});const docs=await InventorySerial.find({companyId:c._id,itemId:item._id,warehouseId:from._id,status:'AVAILABLE',$or:[{serialNumber:{$in:codes}},{barcodeValue:{$in:codes}}]});if(docs.length!==qty)return res.status(409).json({message:`One or more serials for ${item.name} are unavailable or invalid.`});serialIds=docs.map(x=>x._id);}items.push({itemId:item._id,quantity:qty,serialIds,receivedQty:0});}const s=await Shipment.create({companyId:c._id,shipmentNo:text(b.shipmentNo).toUpperCase(),workPackageId:b.workPackageId||null,fromWarehouseId:from._id,toWarehouseId:to._id,agencyId:b.agencyId||to.organizationId||null,driverId:b.driverId||null,vehicleId:b.vehicleId||null,items,status:'DRAFT',priority:['LOW','NORMAL','HIGH','URGENT'].includes(b.priority)?b.priority:'NORMAL',plannedDepartureAt:b.plannedDepartureAt||null,expectedDeliveryAt:b.expectedDeliveryAt||null,routeNotes:text(b.routeNotes)});await platformAudit(req,{companyId:c._id,organizationId:c._id,action:'SHIPMENT_CREATED',entityType:'Shipment',entityId:s._id,after:s.toObject()});res.status(201).json({item:s});};

exports.updateShipment=async(req,res)=>{const c=await company(req,res);if(!c)return;const s=await Shipment.findOne({_id:req.params.id,companyId:c._id});if(!s)return res.status(404).json({message:'Shipment not found.'});if(!['DRAFT','DISPATCHED','IN_TRANSIT'].includes(s.status))return res.status(409).json({message:'Delivered, partial-received or cancelled shipments are locked. Use receipt/reconciliation workflows.'});const before=s.toObject();if(req.body.driverId!==undefined)s.driverId=req.body.driverId||null;if(req.body.vehicleId!==undefined)s.vehicleId=req.body.vehicleId||null;if(req.body.workPackageId!==undefined)s.workPackageId=req.body.workPackageId||null;if(req.body.agencyId!==undefined)s.agencyId=req.body.agencyId||null;if(req.body.expectedDeliveryAt!==undefined)s.expectedDeliveryAt=req.body.expectedDeliveryAt||null;if(req.body.plannedDepartureAt!==undefined&&s.status==='DRAFT')s.plannedDepartureAt=req.body.plannedDepartureAt||null;if(req.body.routeNotes!==undefined)s.routeNotes=text(req.body.routeNotes);if(req.body.priority&&['LOW','NORMAL','HIGH','URGENT'].includes(req.body.priority))s.priority=req.body.priority;if(req.body.issueFlag!==undefined)s.issueFlag=!!req.body.issueFlag;if(req.body.issueNote!==undefined)s.issueNote=text(req.body.issueNote);await s.save();await platformAudit(req,{companyId:c._id,organizationId:s.agencyId||c._id,action:'SHIPMENT_UPDATED',entityType:'Shipment',entityId:s._id,before,after:s.toObject()});res.json({item:s});};

exports.bulkShipments=async(req,res)=>{const c=await company(req,res);if(!c)return;const ids=[...new Set((req.body.ids||[]).map(String).filter(Boolean))].slice(0,100);if(!ids.length)return res.status(400).json({message:'Select at least one shipment.'});const action=text(req.body.action).toUpperCase(),rows=await Shipment.find({_id:{$in:ids},companyId:c._id});let updated=0,skipped=0;for(const s of rows){if(action==='ASSIGN'){if(s.status!=='DRAFT'){skipped++;continue;}if(req.body.driverId!==undefined)s.driverId=req.body.driverId||null;if(req.body.vehicleId!==undefined)s.vehicleId=req.body.vehicleId||null;if(req.body.expectedDeliveryAt!==undefined)s.expectedDeliveryAt=req.body.expectedDeliveryAt||null;await s.save();updated++;}else if(action==='PRIORITY'){if(['DELIVERED','CANCELLED'].includes(s.status)){skipped++;continue;}if(!['LOW','NORMAL','HIGH','URGENT'].includes(req.body.priority)){skipped++;continue;}s.priority=req.body.priority;await s.save();updated++;}else if(action==='CANCEL'){if(s.status!=='DRAFT'){skipped++;continue;}s.status='CANCELLED';s.proofOfDelivery={...(s.proofOfDelivery||{}),cancelReason:text(req.body.reason)||'Bulk draft cancellation',cancelledAt:new Date()};await s.save();updated++;}else return res.status(400).json({message:'Unsupported bulk shipment action.'});}await platformAudit(req,{companyId:c._id,organizationId:c._id,action:`SHIPMENT_BULK_${action}`,entityType:'Shipment',after:{ids,updated,skipped}});res.json({updated,skipped});};

exports.listMaterialIssues=async(req,res)=>{const c=await company(req,res);if(!c)return;const page=Math.max(1,Number(req.query.page||1)),pageSize=Math.min(100,Math.max(10,Number(req.query.pageSize||25))),q={companyId:c._id};if(req.query.agencyId)q.agencyId=req.query.agencyId;if(req.query.technicianUserId)q.technicianUserId=req.query.technicianUserId;if(req.query.workPackageId)q.workPackageId=req.query.workPackageId;if(req.query.status)q.status=req.query.status;if(req.query.q){const rx=new RegExp(escapeRx(text(req.query.q)).slice(0,100),'i');const [techIds,agencyIds]=await Promise.all([User.find({$or:[{username:rx},{mobile:rx}]}).select('_id').limit(1000).lean(),Organization.find({parentOrganization:c._id,type:'AGENCY',$or:[{name:rx},{code:rx}]}).select('_id').limit(1000).lean()]);q.$or=[{issueNo:rx},{notes:rx},{technicianUserId:{$in:techIds.map(x=>x._id)}},{agencyId:{$in:agencyIds.map(x=>x._id)}}];}const [total,items]=await Promise.all([MaterialIssue.countDocuments(q),MaterialIssue.find(q).populate('agencyId','name code').populate('warehouseId','name code').populate('technicianUserId','username mobile').populate('workPackageId','code name').populate('farmerId','beneficiaryId beneficiaryName village district').populate('items.itemId','sku name').sort({issuedAt:-1}).skip((page-1)*pageSize).limit(pageSize).lean()]);res.json({items,total,page,pageSize,pages:Math.max(1,Math.ceil(total/pageSize))});};

exports.fleetHistory=async(req,res)=>{const c=await company(req,res);if(!c)return;const kind=String(req.params.kind||'').toLowerCase();if(!['driver','vehicle'].includes(kind))return res.status(400).json({message:'Invalid fleet record type.'});const key=kind==='driver'?'driverId':'vehicleId',id=req.params.id,page=Math.max(1,Number(req.query.page||1)),pageSize=Math.min(50,Math.max(10,Number(req.query.pageSize||20))),q={companyId:c._id,[key]:id};const [total,items]=await Promise.all([Shipment.countDocuments(q),Shipment.find(q).populate('agencyId','name code').populate('workPackageId','code name geography').populate('driverId','name mobile').populate('vehicleId','registrationNo type').sort({createdAt:-1}).skip((page-1)*pageSize).limit(pageSize).lean()]);res.json({items,total,page,pageSize,pages:Math.max(1,Math.ceil(total/pageSize))});};

// Phase 39 dispatch safety: prevent assigning a moving vehicle/driver to two live trips.
exports.dispatchShipment=async(req,res)=>{const c=await company(req,res);if(!c)return;const s=await Shipment.findOne({_id:req.params.id,companyId:c._id});if(!s)return res.status(404).json({message:'Shipment not found.'});if(s.status!=='DRAFT')return res.status(409).json({message:'Only draft shipments can be dispatched.'});if(s.driverId){const driver=await Driver.findOne({_id:s.driverId,companyId:c._id,isActive:true});if(!driver)return res.status(409).json({message:'Assigned driver is inactive or unavailable. Select another driver.'});if(['OFF_DUTY','INACTIVE'].includes(driver.status))return res.status(409).json({message:'Assigned driver is not available for dispatch.'});const clash=await Shipment.findOne({_id:{$ne:s._id},companyId:c._id,driverId:s.driverId,status:{$in:activeMovingStatuses}}).select('shipmentNo expectedDeliveryAt');if(clash)return res.status(409).json({message:`Driver is already assigned to active shipment ${clash.shipmentNo}. Reassign the dispatch first.`});}if(s.vehicleId){const vehicle=await Vehicle.findOne({_id:s.vehicleId,companyId:c._id,isActive:true});if(!vehicle)return res.status(409).json({message:'Assigned vehicle is inactive or unavailable. Select another vehicle.'});if(['MAINTENANCE','INACTIVE'].includes(vehicle.status))return res.status(409).json({message:'Assigned vehicle is not available for dispatch.'});const clash=await Shipment.findOne({_id:{$ne:s._id},companyId:c._id,vehicleId:s.vehicleId,status:{$in:activeMovingStatuses}}).select('shipmentNo expectedDeliveryAt');if(clash)return res.status(409).json({message:`Vehicle is already assigned to active shipment ${clash.shipmentNo}. Reassign the dispatch first.`});}for(const line of s.items){await balance(c._id,s.fromWarehouseId,line.itemId,-Number(line.quantity),Number(line.quantity));if(line.serialIds?.length)await InventorySerial.updateMany({_id:{$in:line.serialIds},companyId:c._id},{$set:{status:'IN_TRANSIT',warehouseId:null,agencyId:s.agencyId||null}});await StockMovement.create({companyId:c._id,itemId:line.itemId,serialIds:line.serialIds||[],quantity:line.quantity,movementType:'DISPATCH',fromWarehouseId:s.fromWarehouseId,toWarehouseId:s.toWarehouseId,fromOrganizationId:c._id,toOrganizationId:s.agencyId||c._id,referenceType:'Shipment',referenceId:s._id,reason:`Shipment ${s.shipmentNo}`,performedBy:req.platformUser._id});}const raw=crypto.randomBytes(32).toString('hex');s.status='IN_TRANSIT';s.dispatchedAt=new Date();s.trackingTokenHash=hashToken(raw);s.trackingExpiresAt=new Date(Date.now()+1000*60*60*24*7);await s.save();await platformAudit(req,{companyId:c._id,organizationId:c._id,action:'SHIPMENT_DISPATCHED',entityType:'Shipment',entityId:s._id,after:s.toObject()});res.json({item:s,trackingToken:raw,trackingPath:`/track/${raw}`});};

exports.bulkFleet=async(req,res)=>{const c=await company(req,res);if(!c)return;const kind=String(req.body.kind||'').toLowerCase(),ids=[...new Set((req.body.ids||[]).map(String).filter(Boolean))].slice(0,100),action=text(req.body.action).toUpperCase();if(!['driver','vehicle'].includes(kind))return res.status(400).json({message:'Fleet type must be driver or vehicle.'});if(!ids.length)return res.status(400).json({message:'Select at least one fleet record.'});if(!['STATUS','ARCHIVE'].includes(action))return res.status(400).json({message:'Unsupported fleet bulk action.'});const Model=kind==='driver'?Driver:Vehicle,key=kind==='driver'?'driverId':'vehicleId',allowed=kind==='driver'?['AVAILABLE','OFF_DUTY','INACTIVE']:['AVAILABLE','MAINTENANCE','INACTIVE'];const rows=await Model.find({_id:{$in:ids},companyId:c._id});let updated=0,skipped=0;for(const row of rows){const active=await Shipment.countDocuments({companyId:c._id,[key]:row._id,status:{$in:activeMovingStatuses}});if(action==='ARCHIVE'){if(active){skipped++;continue;}row.isActive=false;row.status='INACTIVE';}else{const status=String(req.body.status||'').toUpperCase();if(!allowed.includes(status)){skipped++;continue;}if(active&&status!=='AVAILABLE'){skipped++;continue;}row.status=status;row.isActive=status!=='INACTIVE';}await row.save();updated++;}await platformAudit(req,{companyId:c._id,organizationId:c._id,action:`FLEET_BULK_${action}`,entityType:kind==='driver'?'Driver':'Vehicle',after:{ids,kind,status:req.body.status||null,updated,skipped}});res.json({updated,skipped});};
